import cv2,numpy as np
z=np.load('source_pixels.npz')['rgb'].astype(np.uint8)
# inspect exact source template 0 and current 95 with contour fit using chroma threshold and only target pink ball. use red excess >25 in x80:130 y50:105
for i in [0,31,50,95]:
 im=z[i];p=im.astype(float);s=p[...,0]-(p[...,1]+p[...,2])/2
 if i==0: reg=(slice(48,86),slice(220,256))
 else: reg=(slice(50,105),slice(80,130))
 m=(s>20).astype('uint8');roi=np.zeros_like(m);roi[reg]=m[reg]
 n,lab,st,cent=cv2.connectedComponentsWithStats(roi,8)
 print('\\n',i)
 for j in range(1,n):
  if st[j,4]>100:
   pts=np.column_stack(np.where(lab==j))[:,::-1].astype(np.float32)
   print(st[j],cent[j],cv2.fitEllipse(pts))
